<script>
(function(){
var N='<?php echo esc_js($nonce); ?>', REST='<?php echo esc_js(rest_url()); ?>', SITE='<?php echo esc_js(home_url('/')); ?>';
var H={'X-WP-Nonce':N,'Content-Type':'application/json'};
var S={cats:[],pages:[],items:[],cat:null,q:'',editCat:null};
var $=function(s){return document.querySelector(s)};
function toast(t,err){var e=$('#rkg-toast');e.textContent=t;e.className='rkg-toast on'+(err?' err':'');clearTimeout(e._t);e._t=setTimeout(function(){e.className='rkg-toast'},2600);}
async function api(p,o){o=o||{};o.headers=Object.assign({},H,o.headers||{});o.credentials='same-origin';var r=await fetch(REST+p,o);if(!r.ok){var t=await r.text();throw new Error(r.status+' '+t.slice(0,140));}return r.status===204?null:r.json();}
async function all(p){var out=[],pg=1;while(true){var r=await fetch(REST+p+(p.indexOf('?')>0?'&':'?')+'per_page=100&page='+pg,{headers:H,credentials:'same-origin'});if(!r.ok)break;var d=await r.json();out=out.concat(d);if(d.length<100)break;pg++;}return out;}
async function load(){S.cats=await all('wp/v2/rk_gal_kat?hide_empty=false&_fields=id,name,count,meta');S.pages=await all('wp/v2/pages?_fields=id,title,link&status=publish');S.items=await all('wp/v2/rk_galerija?_fields=id,title,featured_media,rk_gal_kat,menu_order&orderby=menu_order&order=asc');var ids=S.items.map(function(i){return i.featured_media}).filter(Boolean);S.media={};for(var i=0;i<ids.length;i+=100){var m=await all('wp/v2/media?include='+ids.slice(i,i+100).join(',')+'&_fields=id,source_url,media_details');m.forEach(function(x){var s=x.media_details&&x.media_details.sizes;S.media[x.id]=(s&&(s.medium_large||s.large||s.medium)||{}).source_url||x.source_url;});}if(S.cat===null&&S.cats.length)S.cat=S.cats[0].id;render();}
function pageOf(cat){var id=cat&&cat.meta&&cat.meta.rk_page;var p=S.pages.filter(function(x){return x.id==id})[0];return p;}
function render(){var t=$('#rkg-tabs');t.innerHTML='';S.cats.forEach(function(c){var b=document.createElement('button');b.className='rkg-tab'+(c.id===S.cat?' on':'');b.innerHTML=c.name+' <b>'+c.count+'</b>';b.onclick=function(){S.cat=c.id;render();};t.appendChild(b);});var a=document.createElement('button');a.className='rkg-tab add';a.textContent='+ Nauja kategorija';a.onclick=function(){openCat(null)};t.appendChild(a);
 var cat=S.cats.filter(function(c){return c.id===S.cat})[0];var pg=pageOf(cat);$('#rkg-page').textContent=pg?pg.title.rendered:'— nepriskirta —';var v=$('#rkg-view');if(pg){v.href=pg.link;v.style.display=''}else v.style.display='none';
 var q=S.q.toLowerCase();var list=S.items.filter(function(i){return i.rk_gal_kat.indexOf(S.cat)>=0&&(!q||i.title.rendered.toLowerCase().indexOf(q)>=0)});$('#rkg-count').textContent=list.length+' nuotr.';
 var g=$('#rkg-grid');g.innerHTML='';if(!list.length){g.innerHTML='<div class="rkg-empty" style="grid-column:1/-1">Šioje kategorijoje nuotraukų dar nėra. Įkelkite pirmą.</div>';return;}
 list.forEach(function(it,idx){var c=document.createElement('div');c.className='rkg-card';c.draggable=true;c.dataset.id=it.id;var url=S.media[it.featured_media]||'';
  c.innerHTML='<div class="ph" style="background-image:url('+url+')"><span class="n">'+(idx+1)+'</span><button class="x" title="Ištrinti">✕</button></div><div class="bd"><textarea placeholder="Aprašymas po nuotrauka…">'+decode(it.title.rendered)+'</textarea><select></select></div>';
  var sel=c.querySelector('select');S.cats.forEach(function(k){var o=document.createElement('option');o.value=k.id;o.textContent=k.name;if(k.id===S.cat)o.selected=true;sel.appendChild(o);});
  var ta=c.querySelector('textarea');ta.addEventListener('change',async function(){try{await api('wp/v2/rk_galerija/'+it.id,{method:'POST',body:JSON.stringify({title:ta.value})});it.title.rendered=ta.value;toast('Aprašymas išsaugotas');}catch(e){toast('Klaida: '+e.message,1)}});
  sel.addEventListener('change',async function(){try{await api('wp/v2/rk_galerija/'+it.id,{method:'POST',body:JSON.stringify({rk_gal_kat:[+sel.value]})});it.rk_gal_kat=[+sel.value];toast('Perkelta į kitą kategoriją');await load();}catch(e){toast('Klaida: '+e.message,1)}});
  c.querySelector('.x').onclick=async function(){if(!confirm('Ištrinti šią nuotrauką iš galerijos?'))return;try{await api('wp/v2/rk_galerija/'+it.id+'?force=true',{method:'DELETE'});toast('Ištrinta');await load();}catch(e){toast('Klaida: '+e.message,1)}};
  c.addEventListener('dragstart',function(e){S.drag=it.id;c.classList.add('drag');e.dataTransfer.effectAllowed='move'});c.addEventListener('dragend',function(){c.classList.remove('drag');document.querySelectorAll('.overd').forEach(function(x){x.classList.remove('overd')})});
  c.addEventListener('dragover',function(e){e.preventDefault();c.classList.add('overd')});c.addEventListener('dragleave',function(){c.classList.remove('overd')});
  c.addEventListener('drop',async function(e){e.preventDefault();c.classList.remove('overd');if(S.drag===it.id)return;var from=list.findIndex(function(x){return x.id===S.drag}),to=list.findIndex(function(x){return x.id===it.id});var m=list.splice(from,1)[0];list.splice(to,0,m);render();try{for(var i=0;i<list.length;i++){if(list[i].menu_order!==i+1){await api('wp/v2/rk_galerija/'+list[i].id,{method:'POST',body:JSON.stringify({menu_order:i+1})});list[i].menu_order=i+1;}}toast('Eiliškumas išsaugotas');}catch(e2){toast('Klaida: '+e2.message,1)}});
  g.appendChild(c);});}
function decode(s){var d=document.createElement('textarea');d.innerHTML=s;return d.value;}
$('#rkg-q').addEventListener('input',function(){S.q=this.value;render()});
// ikelimas
var drop=$('#rkg-drop'),file=$('#rkg-file');$('#rkg-upload').onclick=function(){file.click()};drop.onclick=function(){file.click()};
drop.addEventListener('dragover',function(e){e.preventDefault();drop.classList.add('over')});drop.addEventListener('dragleave',function(){drop.classList.remove('over')});drop.addEventListener('drop',function(e){e.preventDefault();drop.classList.remove('over');up(e.dataTransfer.files)});file.addEventListener('change',function(){up(file.files);file.value=''});
async function up(files){if(!S.cat){toast('Pirmiausia sukurkite kategoriją',1);return}files=[].slice.call(files).filter(function(f){return /^image\//.test(f.type)});if(!files.length)return;var pr=$('#rkg-prog');pr.style.display='block';var n=0;var max=S.items.reduce(function(m,i){return Math.max(m,i.menu_order||0)},0);
 for(const f of files){try{var fd=new FormData();fd.append('file',f);fd.append('title','Darbu pavyzdys');var r=await fetch(REST+'wp/v2/media',{method:'POST',credentials:'same-origin',headers:{'X-WP-Nonce':N},body:fd});if(!r.ok)throw new Error(r.status);var m=await r.json();var cap=f.name.replace(/\.[^.]+$/,'').replace(/[_-]+/g,' ');await api('wp/v2/rk_galerija',{method:'POST',body:JSON.stringify({title:cap,status:'publish',featured_media:m.id,rk_gal_kat:[S.cat],menu_order:++max})});}catch(e){toast('Nepavyko įkelti '+f.name,1)}n++;pr.firstChild.style.width=Math.round(n/files.length*100)+'%';}
 pr.style.display='none';pr.firstChild.style.width='0';toast('Įkelta: '+n+' nuotr. Aprašymus galite pataisyti kortelėse.');await load();}
// kategorijos
function openCat(c){S.editCat=c;$('#rkg-m-title').textContent=c?'Kategorijos nustatymai':'Nauja kategorija';$('#rkg-m-name').value=c?c.name:'';var s=$('#rkg-m-page');s.innerHTML='<option value="0">— nerodyti —</option>';S.pages.forEach(function(p){var o=document.createElement('option');o.value=p.id;o.textContent=p.title.rendered;if(c&&c.meta&&c.meta.rk_page==p.id)o.selected=true;s.appendChild(o)});$('#rkg-m-del').style.display=c?'':'none';$('#rkg-modal').classList.add('on');$('#rkg-m-name').focus();}
$('#rkg-cat-edit').onclick=function(){openCat(S.cats.filter(function(c){return c.id===S.cat})[0]||null)};$('#rkg-m-cancel').onclick=function(){$('#rkg-modal').classList.remove('on')};
$('#rkg-m-save').onclick=async function(){var name=$('#rkg-m-name').value.trim();if(!name){toast('Įrašykite pavadinimą',1);return}var body={name:name,meta:{rk_page:+$('#rkg-m-page').value}};try{if(S.editCat){await api('wp/v2/rk_gal_kat/'+S.editCat.id,{method:'POST',body:JSON.stringify(body)})}else{var r=await api('wp/v2/rk_gal_kat',{method:'POST',body:JSON.stringify(body)});S.cat=r.id}$('#rkg-modal').classList.remove('on');toast('Kategorija išsaugota');await load();}catch(e){toast('Klaida: '+e.message,1)}};
$('#rkg-m-del').onclick=async function(){if(!S.editCat)return;if(!confirm('Ištrinti kategoriją „'+S.editCat.name+'“? Nuotraukos liks, bet nebebus rodomos svetainėje.'))return;try{await api('wp/v2/rk_gal_kat/'+S.editCat.id+'?force=true',{method:'DELETE'});$('#rkg-modal').classList.remove('on');S.cat=null;toast('Kategorija ištrinta');await load();}catch(e){toast('Klaida: '+e.message,1)}};
load().catch(function(e){toast('Nepavyko įkelti duomenų: '+e.message,1)});
})();
</script>
